'use strict';
const DATA=JSON.parse(document.getElementById('travelData').textContent),E=TripEngine,$=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const CATS={sight:'볼거리·즐길거리',food:'식당',cafe:'카페',hotel:'숙소',transit:'역·터미널'},MODES={car:'자차',taxi:'택시',transit:'대중교통',walk:'도보',rail:'기차',bus:'광역버스'};
const state={region:null,course:0,day:0,selected:null,editUid:null,type:'all',query:'',bathOnly:false,filter:'all',camera:{x:0,y:0,w:500,h:650},width:600,height:650,tween:null,pins:[],flows:[],playing:false,playIndex:0,elapsed:0,flowClock:0,fromPoint:null,playback:null,pane:'map',plannerExpanded:false,plannerView:'timeline',timeZoom:1,pickerQuery:'',pickerType:'all',pickerDay:0,pickerBefore:''};
let saved={},storageOk=true,undo=[],redo=[],pointers=new Map(),gesture=null,ignoreClickUntil=0,pendingTap=null,lastFrame=0,paintTime=0,toastTimer,sortGesture=null,suppressSortClick=0;
