function mutate(fn){if(!plan())return false;stopPlayback();const active=document.activeElement,focusData=active?.dataset?{...active.dataset}:null;const before=JSON.stringify(plan());fn(plan());if(before===JSON.stringify(plan()))return false;undo.push({key:key(),plan:before,day:state.day});if(undo.length>50)undo.shift();redo=[];plan().edited=true;state.playing=false;state.fromPoint=null;persist();refresh(false);if(focusData){const attr=['resizeStop','shiftStop','dragStop','duration','move','action'].find(k=>focusData[k]!==undefined);if(attr){const name='data-'+attr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()),nodes=document.querySelectorAll?.('['+name+']')||[];const target=[...nodes].find(n=>n.dataset[attr]===focusData[attr]&&(!focusData.delta||n.dataset.delta===focusData.delta));target?.focus({preventScroll:true});}}return true;}
function historyStep(back=true){const from=back?undo:redo,to=back?redo:undo,v=from.pop();if(!v)return;stopPlayback();closeStopEditor();if($('dialog')?.dataset.kind==='planner-menu')$('dialog').close();to.push({key:v.key,plan:JSON.stringify(saved[v.key]),day:state.day});saved[v.key]=JSON.parse(v.plan);const[rid,ci]=v.key.split(':');state.editUid=null;persist();if(key()===v.key){state.day=v.day;refresh();}else selectRegion(rid,Number(ci),false);if($('dialog')?.open&&$('dialog').dataset.kind==='place-picker')refreshPicker();if($('dialog')?.open&&$('dialog').dataset.kind==='relocate')$('dialog').close();toast(back?'일정 변경을 되돌렸습니다.':'일정 변경을 다시 적용했습니다.');}
const ICON_PATHS={undo:'M3 7h10a6 6 0 0 1 0 12h-2 M3 7l4-4 M3 7l4 4',redo:'M21 7H11a6 6 0 0 0 0 12h2 M21 7l-4-4 M21 7l-4 4',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',save:'M5 3h12l3 3v15H4V3h1 M8 3v6h8V3 M8 21v-8h8v8',expand:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5',collapse:'M3 8h5V3 M21 8h-5V3 M8 21v-5H3 M16 21v-5h5',plus:'M12 5v14 M5 12h14',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',up:'M12 19V5 M6 11l6-6 6 6',down:'M12 5v14 M6 13l6 6 6-6',grip:'M8 5h.01 M16 5h.01 M8 12h.01 M16 12h.01 M8 19h.01 M16 19h.01'};
