function card(p){const hotel=p.type==='hotel',selected=hotel?plan()?.hotel===p.id:result?.steps.some(x=>x.poi===p.id),bath=p.room?.bathStatus;return`<article class="candidate ${state.selected===p.id?'focused':''}" data-card="${p.id}"><div class="candidate-kicker"><span class="category">${p.aquarium?'◉ 아쿠아리움':CATS[p.type]}${p.fit==='reserve'?' · 예비':''}</span>${selected?`<span class="candidate-selected">${hotel?'선택한 숙소':'일정에 포함'}</span>`:''}</div><button class="card-title" data-focus="${p.id}"><b>${esc(p.name)}</b></button><div class="candidate-meta"><span>${esc(p.area||region().name)}</span><span>${hotel?money(p.cost||0)+'/박':(p.visitMin||60)+'분 권장'}</span></div><p class="candidate-description">${esc(p.desc)}</p>${hotel?`<div class="candidate-bath ${bath==='confirmed'?'confirmed':''}"><b>${bath==='confirmed'?'욕조·스파 확인':'욕조 확약 필요'}</b><span>${esc(p.room?.name||'객실 유형 확인 필요')}</span></div>`:''}<div class="candidate-actions"><button data-add="${p.id}" class="add-btn">${hotel?(selected?'선택한 숙소':('이 숙소로 '+(plan()?.friday?3:2)+'박')):(selected?'＋ 한 번 더':E.date(Math.max(0,state.day))+' ＋ 추가')}</button><button data-detail="${p.id}" class="quiet">정보·예약 ↗</button></div></article>`;}

function renderCandidatePanel(){const d=region();if(!d){$('candidatePanel').innerHTML=`<div class="welcome"><h1 class="welcome-title">11 Travel</h1><div class="welcome-numbers"><b>${DATA.length}<small>지역</small></b><b>${DATA.reduce((n,d)=>n+d.courses.length,0)}<small>코스</small></b><b>${DATA.reduce((n,d)=>n+d.points.length,0)}<small>후보</small></b></div><button class="primary" data-action="choose-region">지역 선택 ↗</button></div>`;return;}
 const scroll=$('candidateList')?.scrollTop||0;
 $('candidatePanel').innerHTML=`<div class="candidate-head"><div class="candidate-title"><h2>장소 후보 <small id="candidateCount"></small></h2><label class="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="장소 검색" placeholder="장소 검색" value="${esc(state.query)}"></label></div><div class="category-tabs" role="group" aria-label="장소 분류">${[['all','전체'],['aquarium','아쿠아리움'],['food','식당'],['cafe','카페'],['sight','즐길거리'],['hotel','숙소']].map(([k,v])=>`<button data-category="${k}" class="${state.type===k?'active':''}" aria-pressed="${state.type===k}">${v}</button>`).join('')}</div><div class="candidate-info">${state.type==='hotel'?`<label class="check"><input id="bathOnly" type="checkbox" ${state.bathOnly?'checked':''}> 욕조 확인만</label>`:'<span>날짜를 고르고 추가하세요</span>'}<label>추가할 날 <select id="addDay" aria-label="장소를 추가할 날짜">${[0,1,2].map(d=>`<option value="${d}" ${d===state.day?'selected':''}>${E.date(d)}</option>`).join('')}</select></label></div></div><div id="candidateList" class="candidate-list"></div>`;
 renderCandidateList();$('candidateList').scrollTop=scroll;
}
function visiblePoints(){return region().points.filter(p=>p.type!=='transit'&&(state.type==='all'||state.type==='aquarium'&&p.aquarium||p.type===state.type)&&(!state.bathOnly||state.type!=='hotel'||p.room?.bathStatus==='confirmed')&&(!state.query||[p.name,p.area,p.desc,...(p.tags||[])].join(' ').toLowerCase().includes(state.query.toLowerCase())));}
function renderCandidateList(){const list=visiblePoints();$('candidateCount').textContent=list.length;$('candidateList').innerHTML=list.length?list.map(card).join(''):`<div class="empty">${state.type==='aquarium'?'이 지역 안에서 현재 운영을 확인한 아쿠아리움 후보가 없습니다.':'조건에 맞는 장소가 없습니다.'}</div>`;}
function openDetail(id){const p=point(id);if(!p)return;pauseMap();state.selected=id;renderPins();$('detailTitle').textContent=p.name;$('detailBody').innerHTML=`<div class="detail-meta">${CATS[p.type]} · ${esc(p.area||'')} ${p.aquarium?'· 아쿠아리움 우선 추천':''}</div><p>${esc(p.desc)}</p>${p.address?`<p class="fine">${esc(p.address)}</p>`:''}${p.type==='hotel'?`<div class="bath ${p.room?.bathStatus==='confirmed'?'confirmed':''}"><b>${esc(p.room?.name||'객실 확인 필요')}</b><span>${esc(p.room?.bathDescription||'개별 객실 욕조 여부 확인 필요')}</span><span>${p.room?.bathStatus==='confirmed'?'공개된 객실 자료에서 욕조·스파 확인':'조건부 후보: 욕조 있는 객실을 확약하기 전 예약하지 마세요.'}</span></div>`:''}<div class="detail-facts"><div><small>권장 체류</small><b>${p.visitMin||60}분</b></div><div><small>${p.type==='hotel'?'객실 1박 계획가':'성인 1인 계획비'}</small><b>${money(p.cost||0)}</b></div></div><p class="fine">${esc(p.costNote||'가격은 계획용이며 실제 예약 조건에 따라 달라집니다.')}</p><h3>운영·예약 확인</h3><p>${esc(p.hours?.note||'영업시간은 방문일에 맞춰 확인이 필요합니다.')}</p>${p.roadAccessNote?`<p class="fine">${esc(p.roadAccessNote)}</p>`:''}<div class="detail-links">${venueLinks(p)}<a href="${mapUrl(p)}" target="_blank" rel="noopener noreferrer">실제 지도·길찾기 ↗</a>${p.room?.evidenceUrl?`<a href="${esc(p.room.evidenceUrl)}" target="_blank" rel="noopener noreferrer">욕조·객실 근거 ↗</a>`:''}</div><div class="detail-add"><label>추가할 날<select id="detailDay">${[0,1,2].map(d=>`<option value="${d}" ${d===state.day?'selected':''}>${E.date(d)}</option>`).join('')}</select></label><button class="primary" data-add-detail="${p.id}">${p.type==='hotel'?'이 숙소 선택':'내 일정에 추가'}</button><button class="quiet" data-run-point="${p.id}">여기서 경로 재생 ▶</button></div>`;$('detail').showModal();}
function findItem(uid){const p=plan();if(!p)return null;for(let day=0;day<3;day++){const index=p.items[day].findIndex(x=>x.uid===uid);if(index>=0)return{item:p.items[day][index],day,index};}return null;}
function addPoint(id,day=state.day,beforeUid=''){day=E.clamp(Math.trunc(Number(day)||0),0,2);const p=point(id);if(!p||p.type==='transit')return false;if(p.type==='hotel'){const changed=mutate(q=>q.hotel=id);if(changed)toast(p.name+'으로 숙소 변경',true);return changed;}if(plan().items[day].length>=30){toast('하루에는 최대 30곳까지 추가할 수 있습니다.');return false;}const uid=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);state.day=day;state.editUid=uid;state.selected=id;mutate(q=>{const pos=q.items[day].findIndex(x=>x.uid===beforeUid);q.items[day].splice(pos<0?q.items[day].length:pos,0,{uid,poi:id,duration:p.visitMin||60,start:null,mode:null,travel:null});});revealStop(uid);toast(E.date(day)+' · '+p.name+' 추가',true);return true;}
function removeStop(uid){const v=findItem(uid);if(!v)return false;const name=point(v.item.poi).name,nextUid=plan().items[v.day][v.index+1]?.uid||plan().items[v.day][v.index-1]?.uid;const changed=mutate(p=>{p.items[v.day].splice(v.index,1);if(state.editUid===uid)state.editUid=null;});if(changed){const next=[...(document.querySelectorAll?.('[data-edit]')||[])].find(n=>n.dataset.edit===nextUid&&n.offsetParent!==null);(next||document.querySelector?.('.add-place'))?.focus({preventScroll:true});toast(name+' 삭제',true);}return changed;}
function adjustDuration(uid,delta){const v=findItem(uid);if(!v||!Number.isFinite(delta))return false;return mutate(()=>v.item.duration=E.clamp(Math.round(v.item.duration+delta),15,720));}
function moveStop(uid,day,index){const v=findItem(uid);if(!v||!Number.isInteger(day)||day<0||day>2||!Number.isFinite(index))return false;const target=plan().items[day];if(v.day!==day&&target.length>=30){toast('옮길 날짜에 이미 30곳이 있습니다.');return false;}index=E.clamp(Math.trunc(index),0,target.length-(day===v.day?1:0));if(v.day===day&&v.index===index)return false;state.day=day;state.editUid=uid;return mutate(p=>{p.items[v.day].splice(v.index,1);p.items[day].splice(index,0,v.item);});}
function shiftStop(uid,delta){const v=findItem(uid);if(!v)return false;return moveStop(uid,v.day,v.index+delta);}
function setPlannerView(view){state.plannerView=view==='sequence'?'sequence':'timeline';renderPlanner();}
function revealStop(uid){const b=result?.days.flatMap(d=>d.blocks).find(b=>b.uid===uid),scroll=$('timeScroll'),canvas=$('timeCanvas');if(b&&scroll&&canvas){const width=canvas.scrollWidth||1440*state.timeZoom;scroll.scrollLeft=Math.max(0,Math.min(b.start,1439)/1440*width-(scroll.clientWidth||600)*.3);}const rail=$('sequenceScroll');if(state.plannerView==='sequence'&&rail){const card=[...(rail.querySelectorAll?.('[data-sort-item]')||[])].find(x=>x.dataset.sortItem===uid);card?.scrollIntoView({block:'nearest',inline:'nearest',behavior:motion.matches?'auto':'smooth'});}}
function focusTimeline(){const day=result?.days.find(d=>d.day===state.day),b=day?.blocks.find(b=>b.kind==='visit')||day?.blocks.find(b=>b.start>0),canvas=$('timeCanvas'),scroll=$('timeScroll');if(!scroll||!canvas)return;scroll.scrollLeft=Math.max(0,((b?.start||480)-45)/1440*(canvas.scrollWidth||1440*state.timeZoom));}
function changeTimeZoom(delta){const sc=$('timeScroll'),canvas=$('timeCanvas'),width=canvas?.scrollWidth||1440*state.timeZoom,center=((sc?.scrollLeft||0)+(sc?.clientWidth||0)/2)/width;state.timeZoom=E.clamp(state.timeZoom+delta,1,3);renderPlanner();const next=$('timeCanvas')?.scrollWidth||1440*state.timeZoom;if($('timeScroll'))$('timeScroll').scrollLeft=Math.max(0,center*next-($('timeScroll').clientWidth||0)/2);}
function renderPlanner(){const d=region();$('planner').hidden=!d;if(!d)return;const p=plan(),s=result,dayData=s.days.find(x=>x.day===state.day)||s.days.find(x=>x.day===0),day=dayData.day,visits=dayData.blocks.filter(b=>b.kind==='visit');
 const sc=$('timeScroll')?.scrollLeft,prevDay=$('timeScroll')?.dataset.day,railScroll=$('sequenceScroll')?.scrollLeft,bodyScroll=$('plannerBody')?.scrollTop;
 $('planner').className='planner'+(state.plannerExpanded?' expanded':'');
 $('planner').innerHTML=`<div class="planner-top"><h2>일정 <small>${p.friday?'3박 4일':'2박 3일'}</small></h2><div class="planner-view-buttons" role="group" aria-label="일정 보기 방식"><button data-planner-view="timeline" aria-pressed="${state.plannerView==='timeline'}">시간표</button><button data-planner-view="sequence" aria-pressed="${state.plannerView==='sequence'}">방문 순서</button></div><div class="planner-tools"><button data-action="undo" ${undo.length?'':'disabled'} aria-label="되돌리기" title="되돌리기 (⌘/Ctrl Z)">${icon('undo')}</button><button data-action="redo" ${redo.length?'':'disabled'} aria-label="다시 실행" title="다시 실행 (⌘/Ctrl Shift Z)">${icon('redo')}</button><button data-action="settings" aria-label="출발·이동·숙소 설정" title="출발·이동·숙소">${icon('settings')}</button><button data-action="save" aria-label="일정 저장·가져오기" title="저장·가져오기">${icon('save')}</button><button class="planner-more" data-action="planner-menu" aria-label="일정 관리 메뉴">···</button><button data-action="expand-planner" aria-expanded="${state.plannerExpanded}" aria-label="${state.plannerExpanded?'일정표 접기':'일정표 크게 보기'}" title="${state.plannerExpanded?'접기':'크게 보기'}">${icon(state.plannerExpanded?'collapse':'expand')}</button></div></div>
 <div class="planner-days"><div class="day-buttons" role="group" aria-label="여행 날짜">${(p.friday?[-1,0,1,2]:[0,1,2]).map(v=>`<button data-plan-day="${v}" aria-pressed="${v===day}" class="${v===day?'active':''}">${E.date(v)}<span>${v<0?'선출발':p.items[v].length+'곳'}</span></button>`).join('')}</div><div class="timeline-actions"><button class="add-place" data-action="add-place">${icon('plus')}<span>장소</span></button><button id="playRoute" data-action="play">▶ 일정 시작</button></div></div>
 <div class="planner-body" id="plannerBody"><div class="time-scroll" id="timeScroll" data-day="${day}" ${state.plannerView==='timeline'?'':'hidden'} tabindex="0" aria-label="${E.date(day)} 24시간 일정표. 좌우 화살표로 스크롤, 장소 선택으로 편집"><div class="time-canvas" id="timeCanvas" style="min-width:${1440*state.timeZoom}px"><div class="hour-ruler">${Array.from({length:25},(_,i)=>`<span style="left:${i/24*100}%">${String(i).padStart(2,'0')}</span>`).join('')}</div><div class="time-row">${dayData.blocks.map((b,i)=>timeBlock(b,i)).join('')}</div></div></div>
 <div class="sequence-scroll" id="sequenceScroll" ${state.plannerView==='sequence'?'':'hidden'}>${sequenceHtml(visits,dayData,state.plannerExpanded)}</div>${state.plannerExpanded&&state.plannerView==='timeline'?`<div class="planner-extra"><div class="extra-heading"><span>방문 순서</span><small>손잡이로 순서 이동 · ＋ / −로 체류시간 조절</small></div>${state.plannerView==='timeline'?sequenceHtml(visits,dayData,true):''}</div>`:''}</div>
 <div class="planner-foot"><div class="timeline-zoom" ${state.plannerView==='timeline'?'':'hidden'}><button data-action="time-out" ${state.timeZoom<=1?'disabled':''} aria-label="시간표 축소">−</button><span>${Math.round(state.timeZoom*100)}%</span><button data-action="time-in" ${state.timeZoom>=3?'disabled':''} aria-label="시간표 확대">＋</button><button class="jump-time" data-action="fit-day">첫 일정</button></div><span class="day-totals">${visits.length}곳<span> · 방문 ${durationLabel(dayData.visitMin)} · 이동 ${durationLabel(dayData.travelMin)}</span></span><button class="planner-health ${s.returnMinute>960||s.unconfirmedService?'late':''}" data-action="schedule-info" aria-label="귀환 시간과 일정 확인">귀환 ${E.time(s.returnMinute)}${s.warnings.length?`<i>${s.warnings.length}</i>`:''}</button></div>`;
 if(sc!==undefined&&String(day)===prevDay)$('timeScroll').scrollLeft=sc;else focusTimeline();if($('sequenceScroll'))$('sequenceScroll').scrollLeft=String(day)===prevDay?railScroll||0:0;if($('plannerBody'))$('plannerBody').scrollTop=bodyScroll||0;updatePlaybackControls();
}
function sequenceHtml(visits,dayData,vertical=false){if(!visits.length)return`<div class="schedule-empty"><div><b>${state.day<0?'금요일은 이동과 숙박':'아직 정한 장소가 없습니다'}</b><span>${state.day<0?'출발 시각과 숙소는 설정에서 변경하세요.':'후보를 골라 이 날짜에 추가하세요.'}</span></div><button data-action="${state.day<0?'settings':'add-place'}">${state.day<0?'설정 열기':'＋ 장소 추가'}</button></div>`;return`<ol class="sequence-list ${vertical?'vertical':''}">${visits.map((b,i)=>{const v=findItem(b.uid),prev=dayData.blocks.find(x=>x.uid==='travel-'+b.uid),p=point(b.poi);return`<li class="stop-card ${state.editUid===b.uid?'selected':''}" data-sort-item="${b.uid}"><div class="stop-card-top"><button class="drag-handle" data-drag-stop="${b.uid}" aria-label="${esc(b.title)} 순서 이동. 위아래 화살표로 이동" title="끌어서 순서 이동">${icon('grip')}</button><span class="stop-index">${String(i+1).padStart(2,'0')}</span><span class="stop-category">${p.aquarium?'아쿠아리움':CATS[p.type]}</span><button class="stop-delete" data-remove-stop="${b.uid}" aria-label="${esc(b.title)} 일정에서 삭제">${icon('trash')}</button></div><button class="stop-main" data-edit="${b.uid}"><strong>${esc(b.title)}</strong><span>${E.time(b.start)} — ${E.time(b.end)}</span></button><div class="stop-controls"><div class="mini-stepper"><button data-resize-stop="${b.uid}" data-delta="-15" ${b.duration<=15?'disabled':''} aria-label="${esc(b.title)} 15분 줄이기">−</button><span>${durationLabel(b.duration)}</span><button data-resize-stop="${b.uid}" data-delta="15" ${b.duration>=720?'disabled':''} aria-label="${esc(b.title)} 15분 늘리기">＋</button></div><div class="stop-order"><button data-shift-stop="${b.uid}" data-delta="-1" ${i===0?'disabled':''} aria-label="${esc(b.title)} 한 칸 앞으로">${icon('up')}</button><button data-shift-stop="${b.uid}" data-delta="1" ${i===visits.length-1?'disabled':''} aria-label="${esc(b.title)} 한 칸 뒤로">${icon('down')}</button></div></div><div class="stop-card-foot">${prev?`<button class="stop-transfer" data-travel-index="${dayData.blocks.indexOf(prev)}" data-travel-from="${prev.from}" data-travel-to="${prev.to}" aria-label="${esc(prev.title)} 이동시간 확인">${MODES[prev.mode]||'이동'} ${durationLabel(prev.minutes)} ↗</button>`:'<span>이동 없음</span>'}<button data-relocate="${b.uid}">날짜·순서 변경 ↗</button></div></li>`;}).join('')}<li class="stop-add"><button data-action="add-place">${icon('plus')}장소 추가</button></li></ol>`;}
function stopListHtml(visits){const day=result.days.find(d=>d.day===state.day);return`<div class="day-stop-list">${sequenceHtml(visits,day,true)}</div>`;}
function dayList(){const day=result.days.find(d=>d.day===state.day);modal(E.date(state.day)+' · 방문 순서',stopListHtml(day?.blocks.filter(b=>b.kind==='visit')||[]));$('dialog').dataset.kind='day-list';}
function openPlacePicker(){state.pickerDay=Math.max(0,state.day);state.pickerQuery='';state.pickerType='all';state.pickerBefore='';modal('장소 추가',pickerHtml());$('dialog').dataset.kind='place-picker';}
function pickerHtml(){const items=plan().items[state.pickerDay],list=region().points.filter(p=>!['hotel','transit'].includes(p.type)&&(state.pickerType==='all'||state.pickerType==='aquarium'&&p.aquarium||state.pickerType===p.type)&&(!state.pickerQuery||[p.name,p.desc,p.area].join(' ').toLowerCase().includes(state.pickerQuery.toLowerCase())));return`<div class="picker-controls"><label>날짜<select id="pickerDay">${[0,1,2].map(d=>`<option value="${d}" ${d===state.pickerDay?'selected':''}>${E.date(d)}</option>`).join('')}</select></label><label>추가 위치<select id="pickerBefore"><option value="">마지막에 추가</option>${items.map((v,i)=>`<option value="${v.uid}" ${v.uid===state.pickerBefore?'selected':''}>${i+1}. ${esc(point(v.poi).name)} 앞</option>`).join('')}</select></label></div><label class="picker-search"><span class="sr-only">추가할 장소 검색</span><input id="pickerSearch" type="search" placeholder="장소·카페·식당 검색" value="${esc(state.pickerQuery)}" autocomplete="off"></label><div class="category-tabs">${[['all','전체'],['aquarium','아쿠아리움'],['food','식당'],['cafe','카페'],['sight','즐길거리']].map(([k,n])=>`<button data-picker-type="${k}" aria-pressed="${k===state.pickerType}">${n}</button>`).join('')}</div><div class="picker-results">${list.map(p=>`<article class="picker-place"><div><b>${esc(p.name)}</b><small>${esc(p.area||'')} · ${durationLabel(p.visitMin||60)}${items.some(v=>v.poi===p.id)?' · 이 날짜에 포함':''}</small><p>${esc(p.desc)}</p></div><button data-pick="${p.id}" aria-label="${esc(p.name)} 추가">${icon('plus')}</button></article>`).join('')||'<p class="empty">조건에 맞는 장소가 없습니다.</p>'}</div>`;}
function refreshPicker(){if($('dialog').dataset.kind!=='place-picker')return;const focus=document.activeElement?.id,start=document.activeElement?.selectionStart,scroll=$('dialogBody').scrollTop;$('dialogBody').innerHTML=pickerHtml();$('dialogBody').scrollTop=scroll;if(focus){$(focus)?.focus({preventScroll:true});if(focus==='pickerSearch'&&typeof start==='number')$(focus)?.setSelectionRange?.(start,start);}}
function relocateStop(uid){const v=findItem(uid);if(!v)return;state.editUid=uid;modal('날짜·순서 변경',`<p class="relocate-name">${esc(point(v.item.poi).name)}</p><div class="picker-controls"><label>옮길 날짜<select id="moveDay">${[0,1,2].map(d=>`<option value="${d}" ${d===v.day?'selected':''}>${E.date(d)}</option>`).join('')}</select></label><label>방문 위치<select id="movePosition">${moveOptions(v.day,uid,v.index)}</select></label></div><p class="fine">변경한 순서로 이동시간과 다음 일정을 다시 계산합니다.</p><button class="primary full" data-action="apply-move">이 위치로 이동</button>`);$('dialog').dataset.kind='relocate';}
function moveOptions(day,uid,index=0){const items=plan().items[day].filter(v=>v.uid!==uid);return items.map((v,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${esc(point(v.poi).name)} 앞</option>`).join('')+`<option value="${items.length}" ${index>=items.length?'selected':''}>마지막</option>`;}
function scheduleInfo(){const s=result;modal('일정 확인',`<div class="schedule-summary"><div><small>월요일 ${esc(s.returnHub)}</small><b class="${s.returnMinute>960||s.unconfirmedService?'late':'on-time'}">${E.time(s.returnMinute)} 도착 계획</b></div><div><small>두 사람 예상 비용</small><b>${money(s.cost)}</b></div></div><p class="fine">${storageOk?'자동 저장됨':'파일 저장을 이용하세요'} · 영업시간 확인 필요 ${s.hoursUnconfirmed.length}곳</p>${s.warnings.length?`<ul class="schedule-warning-list">${[...new Set(s.warnings)].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>현재 일정에 시간 겹침이나 알려진 휴무 경고가 없습니다.</p>'}`);}

function timeBlock(b,index=0){if(b.start>=1440||b.end<=0||b.end<=b.start)return'';const left=E.clamp(b.start,0,1440)/1440*100,width=Math.max(.05,(Math.min(b.end,1440)-Math.max(b.start,0))/1440*100),uid=b.kind==='visit'?`data-edit="${b.uid}"`:b.kind==='travel'?`data-travel-index="${index}" data-travel-info="${esc(b.uid||'')}" data-travel-from="${b.from}" data-travel-to="${b.to}"`:`data-block-info="${esc(b.title)}"`;
 return`<button class="time-block ${b.kind} ${b.uid===state.editUid?'active':''}" style="left:${left}%;width:${width}%" ${uid} title="${esc(b.title+' · '+E.time(b.start)+'–'+E.time(b.end))}" aria-label="${esc(b.title+' '+E.time(b.start)+'부터 '+E.time(b.end))}"><span>${b.kind==='travel'?MODES[b.mode]||'이동':esc(b.title)}</span><small>${E.time(b.start)}${b.kind==='visit'?' · '+durationLabel(b.end-b.start):''}</small></button>`;}
function selectedItem(){return findItem(state.editUid);}
function editorHtml(){const v=selectedItem();if(!v)return`<div class="editor-empty">시간표의 장소 블록을 선택하면 <b>머무는 시간·방문 순서·이동시간</b>을 조절할 수 있습니다.</div>`;const p=point(v.item.poi),b=result.days.flatMap(d=>d.blocks).find(x=>x.uid===v.item.uid),travel=result.days.flatMap(d=>d.blocks).find(x=>x.uid==='travel-'+v.item.uid);return`<div class="stop-editor"><div class="edit-name"><b>${esc(p.name)}</b><span>${E.time(b?.start||0)}–${E.time(b?.end||0)}</span><button data-action="detail-selected">정보·예약 ↗</button></div><div class="edit-fields"><label>방문일<select id="editDay">${[0,1,2].map(d=>`<option value="${d}" ${d===v.day?'selected':''}>${E.date(d)}</option>`).join('')}</select></label><div class="duration-field"><label for="duration">머무는 시간</label><div class="stepper"><button data-duration="-15" aria-label="체류시간 15분 줄이기">−</button><input id="duration" type="number" min="15" max="720" step="15" value="${v.item.duration}" aria-label="체류시간 분"><span>분</span><button data-duration="15" aria-label="체류시간 15분 늘리기">＋</button></div></div><label>희망 시작 <small>비우면 자동</small><input id="preferredStart" type="time" value="${v.item.start===null?'':E.time(v.item.start)}"></label><label>이전 장소에서<select id="legMode">${modeOptions(v.item.mode||plan().mode)}</select></label><label>이동시간 <small>예상 ${travel?.minutes||0}분</small><input id="legMinutes" type="number" min="0" max="600" placeholder="자동 계산" value="${v.item.travel??''}"></label></div><div class="edit-actions"><button data-move="-1" ${v.index===0?'disabled':''}>↑ 앞으로</button><button data-move="1" ${v.index===plan().items[v.day].length-1?'disabled':''}>↓ 뒤로</button><button data-action="clear-start">시작·이동 자동 계산</button><button data-action="remove" class="danger">일정에서 삭제</button></div></div>`;}
function modeOptions(mode){return[['car','자차'],['taxi','택시'],['transit','대중교통'],['walk','도보']].filter(([m])=>m!=='car'||region().carAllowed).map(([m,n])=>`<option value="${m}" ${mode===m?'selected':''}>${n}</option>`).join('');}
function editSelect(uid){stopPlayback();state.editUid=uid;const v=selectedItem();if(!v)return;state.day=v.day;state.selected=v.item.poi;renderPlanner();renderCandidatePanel();renderPins();renderRoutes();focusMap(point(v.item.poi));modal('일정 수정',editorHtml());$('dialog').dataset.kind='stop-editor';}
function updateStopEditor(){if($('dialog')?.open&&$('dialog').dataset.kind==='day-list'){const day=result.days.find(d=>d.day===state.day);$('dialogBody').innerHTML=stopListHtml(day?.blocks.filter(b=>b.kind==='visit')||[]);}if($('dialog')?.open&&$('dialog').dataset.kind==='stop-editor'){if(!selectedItem()){closeStopEditor();return;}const focus=document.activeElement?.id,scroll=$('dialogBody').scrollTop;$('dialogBody').innerHTML=editorHtml();$('dialogBody').scrollTop=scroll;if(focus)$(focus)?.focus({preventScroll:true});}}
function closeStopEditor(){cancelSort();if($('dialog')?.dataset.kind==='stop-editor'){$('dialog').close();$('dialog').dataset.kind='';}}

function modal(title,html){cancelSort();pauseMap();$('dialog').dataset.kind='';$('dialogTitle').textContent=title;$('dialogBody').innerHTML=html;$('dialog').showModal();}
function settings(){const r=region(),p=plan(),fridayPreview=E.schedule(r,{...p,friday:true}),fridayCheckin=fridayPreview.days.find(d=>d.day===-1)?.blocks.find(b=>b.kind==='hotel')?.start;modal('출발·이동·숙소 설정',`<div class="setting-grid"><label>현지 기본 이동<select id="defaultMode">${modeOptions(p.mode)}</select></label>${!r.carAllowed?`<label>부산 내 역·터미널까지<input id="busanAccess" type="number" min="0" max="180" value="${p.busanAccess}">분 · 집/직장 위치에 맞춰 조절</label>`:''}<label>토요일 부산 출발 준비<input id="departSaturday" type="time" value="${E.time(p.departSaturday)}"></label>${[0,1,2].map(d=>`<label>${E.date(d)} 숙소에서 나오는 시각<input data-day-start="${d}" type="time" value="${E.time(p.starts[d])}"></label>`).join('')}<label>같은 객실로 연박할 숙소<select id="hotelSelect">${r.points.filter(x=>x.type==='hotel').map(x=>`<option value="${x.id}" ${x.id===p.hotel?'selected':''}>${esc(x.name)} · ${x.room?.bathStatus==='confirmed'?'욕조 확인':'확약 필요'}</option>`).join('')}</select></label></div><label class="check friday"><input type="checkbox" id="friday" ${p.friday?'checked':''}> 금요일 11/27 밤에 미리 출발하고 같은 숙소 1박 추가</label><label class="friday-time">금요일 부산 출발 준비<input id="departFriday" type="time" value="${E.time(p.departFriday)}"></label><div class="notice"><b>${r.arrival.friday?.recommended?'이 지역은 금요일 선출발 이점이 있습니다.':'이 지역은 토요일 출발을 우선 추천합니다.'}</b><p>${esc(r.arrival.friday?.benefit||'토요일 이동시간을 줄일 수 있지만 숙박비가 늘어납니다.')}</p><p>현재 선택 숙소 기준 추가 ${money(point(p.hotel).cost||150000)} + 금요일 식비·교통비. 현재 설정의 예상 체크인 ${E.time(fridayCheckin||0)}${fridayPreview.unconfirmedService?' · 실제 배차 확인 필요':''}.</p><p>도착 후: ${esc(r.arrival.friday?.activities||'체크인과 객실 휴식')}. 늦은 입실은 숙소에 확인하세요.</p></div><h3>교통 계획 기준</h3><p>${esc(r.arrival.summary)}<br>${esc(r.return.summary)}</p><p class="fine">이동 블록에서 소요시간·길찾기를 확인하고 시간을 조절할 수 있습니다. 열차·버스는 방문일 시간표를 확인해 예약하세요.</p><a class="link-btn" href="${esc(r.arrival.bookingUrl||'https://www.korail.com/')}" target="_blank" rel="noopener">광역 교통 예약·시간표 ↗</a><button class="primary full" data-action="apply-settings">설정 적용</button>`);}
function saveDialog(){modal('내 일정 저장·가져오기',`<p>이 브라우저에는 자동 저장됩니다. 기기를 바꿀 때는 아래 파일 저장을 사용하세요.</p><div class="save-actions"><button class="primary" data-action="download-json">전체 편집 일정 JSON 저장</button><button class="primary" data-action="download-html">내 일정이 포함된 travel.html 저장</button><label class="upload">저장한 JSON 가져오기<input id="importFile" type="file" accept=".json,application/json"></label></div><p class="fine">파일에는 여행 일정만 들어갑니다. 가져오기는 같은 지역·추천 코스의 현재 편집본을 바꿉니다. 기존 파일 형식과 장소가 유효한지 먼저 검사합니다.</p><p id="importStatus" role="status"></p>`);}
function download(name,text,type){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function resetPlan(blank=false){mutate(p=>{const fresh=E.createPlan(region(),state.course);if(blank){fresh.items=[[],[],[]];fresh.name='직접 만든 일정';}Object.assign(p,fresh);state.editUid=null;});toast(blank?'빈 일정에서 장소를 골라보세요.':'추천 코스 원안을 불러왔습니다.');}
function info(){modal('사용 안내',`<dl class="help-list"><div><dt>지역·코스</dt><dd>지역을 고른 뒤 추천 코스를 선택하세요.</dd></div><div><dt>장소 추가</dt><dd>후보 목록 또는 일정의 <b>＋ 장소</b>에서 추가<br>날짜와 추가 위치도 선택할 수 있어요.</dd></div><div><dt>일정 편집</dt><dd><b>시간표</b>에서 장소를 눌러 상세 편집<br><b>방문 순서</b>에서 ＋ / −, 순서 이동, 삭제</dd></div><div><dt>지도 조작</dt><dd>드래그로 이동 · 두 손가락 또는 + / −로 확대·축소<br><b>일정 시작</b>을 누르면 화면이 경로를 따라갑니다.</dd></div><div><dt>예약·저장</dt><dd>장소 상세에서 예약 링크 확인<br><b>저장</b>에서 일정 파일 저장</dd></div></dl><div class="help-key" aria-label="지도 범례"><span><i class="key-current"></i>내 일정</span><span><i class="key-course"></i>다른 코스</span><span><i class="key-candidate"></i>후보</span></div><small class="help-note">화살표는 이동 순서이며 실제 도로 경로는 아닙니다.</small>`);}
function chooseRegion(){modal('지역 선택',`<div class="region-picker">${DATA.map(d=>`<button data-region="${d.id}">${esc(d.name)}<small>${d.courses.length}코스</small></button>`).join('')}</div>`);}
/* Geographic overview and input handling. No map SDK or external tile request. */
const project=c=>({x:(c[0]-124)*80,y:(40-c[1])*100});
function fit(coords,pad=.2,min=3){const pts=coords.map(project),xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),cx=(Math.max(...xs)+Math.min(...xs))/2,cy=(Math.max(...ys)+Math.min(...ys))/2,ratio=state.width/state.height;let w=Math.max(min,Math.max(...xs)-Math.min(...xs))*(1+pad*2),h=Math.max(min,Math.max(...ys)-Math.min(...ys))*(1+pad*2);if(w/h<ratio)w=h*ratio;else h=w/ratio;return{x:cx-w/2,y:cy-h/2,w,h};}
function nationalView(){return fit([[125.65,33.15],[130.35,38.73]],.075,100);}
function fitSelected(){pauseMap();if(!region()){animateView(nationalView());return;}animateView(fit(region().points.filter(p=>p.type!=='transit').map(p=>p.coord),.18,3));}
function focusMap(p){pauseMap();const v=project(p.coord),w=Math.min(state.camera.w,9),h=w*state.height/state.width;animateView({x:v.x-w/2,y:v.y-h/2,w,h},250);}
const lerp=(a,b,t)=>a+(b-a)*t;
function animateView(to,duration=320){state.tween={from:{...state.camera},to,start:performance.now(),duration:motion.matches?0:duration};}
function screen(c){const p=project(c),v=state.camera;return{x:(p.x-v.x)/v.w*state.width,y:(p.y-v.y)/v.h*state.height};}
function curve(a,b){const p=project(a.coord),q=project(b.coord),dx=q.x-p.x,dy=q.y-p.y,len=Math.hypot(dx,dy)||1,bend=Math.min(len*.12,35);return{p,q,c:{x:(p.x+q.x)/2-dy/len*bend,y:(p.y+q.y)/2+dx/len*bend}};}
function curvePoint(c,t){return{x:(1-t)**2*c.p.x+2*(1-t)*t*c.c.x+t*t*c.q.x,y:(1-t)**2*c.p.y+2*(1-t)*t*c.c.y+t*t*c.q.y};}
const curvePath=c=>`M${c.p.x},${c.p.y} Q${c.c.x},${c.c.y} ${c.q.x},${c.q.y}`;
function renderPins(){let list=[];const d=region();if(!d){for(const r of filteredRegions()){list.push(...r.points.filter(p=>p.type!=='transit').map(p=>({p,owner:r.id,global:true,layer:'candidate'})));list.push({p:{id:r.id,name:r.name,coord:r.center,type:'region'},region:true,layer:'destination'});}list.push({p:E.ORIGIN,layer:'origin'});}else{const selected=new Set(result.steps.map(x=>x.poi)),other=new Set(d.courses.flatMap(c=>c.days.flat()));list=d.points.map(p=>({p,layer:selected.has(p.id)?'selected':other.has(p.id)?'alternate':'candidate'}));list.push({p:E.origin(d,state.day===2),layer:'origin'});}
 $('pins').innerHTML=list.map(x=>`<button class="map-pin local layer-${x.layer} ${x.global?'global-poi':''} ${x.layer==='candidate'||x.layer==='alternate'?'reserve':''} ${state.selected===x.p.id?'current':''}" data-pin="${x.p.id}" ${x.owner?`data-owner="${x.owner}"`:''} ${x.region?'data-destination="true"':''} data-type="${x.p.type}" aria-label="${esc((x.owner?DATA.find(d=>d.id===x.owner).name+' · ':'')+x.p.name)} · ${x.region?'여행 지역':x.layer==='selected'?'내 일정':'후보 장소'}"><span class="leader"></span><span class="pin-dot"></span><span class="pin-label">${x.p.aquarium?'◉ ':''}${esc(x.p.name)}</span></button>`).join('');state.pins=list.map((x,i)=>({...x,el:$('pins').children[i]}));paintMap();}
function updatePins(){const boxes=[],co=new Map(),detail=E.clamp((250-state.camera.w)/180,0,1),ordered=[...state.pins].sort((a,b)=>(b.p.id===state.selected?8:0)+(b.layer==='selected'?2:0)+(b.region?4:0)-((a.p.id===state.selected?8:0)+(a.layer==='selected'?2:0)+(a.region?4:0)));
 for(const x of ordered){const p=screen(x.p.coord),k=(x.owner||'')+x.p.coord.join(','),n=co.get(k)||0;co.set(k,n+1);if(n){p.x+=Math.cos(n*2.4)*Math.min(42,16+n*9);p.y+=Math.sin(n*2.4)*Math.min(42,16+n*9);}x.el.hidden=p.x<-24||p.x>state.width+24||p.y<-24||p.y>state.height+24;if(x.el.hidden)continue;x.el.style.left=p.x+'px';x.el.style.top=p.y+'px';if(x.global){x.el.style.opacity=String(.12+detail*.65);x.el.style.pointerEvents=detail>.25?'auto':'none';}
 const l=x.el.querySelector('.pin-label');if(x.global&&state.camera.w>95){l.style.visibility='hidden';continue;}const w=Math.min(150,x.p.name.length*11+20),h=27,opts=[[14,-h/2],[-w-14,-h/2],[12,16],[-w-12,16],[12,-h-16],[-w-12,-h-16]];let off=null;for(const[dx,dy]of opts){const b={x:p.x+dx,y:p.y+dy,w,h};if(b.x<4||b.x+w>state.width-4||b.y<4||b.y+h>state.height-4)continue;if(!boxes.some(o=>b.x<o.x+o.w+4&&b.x+w+4>o.x&&b.y<o.y+o.h+3&&b.y+h+3>o.y)){off=[dx,dy];boxes.push(b);break;}}
 l.style.visibility=off||state.selected===x.p.id?'visible':'hidden';off=off||[12,12];l.style.left=24+off[0]+'px';l.style.top=24+off[1]+'px';}
}
const recommendationCache=new Map();
function renderRoutes(){const edges=[],seen=new Set(),d=region();function add(a,b,kind,day=0){if(!a||!b||a.id===b.id||a.coord.join()==b.coord.join())return;const key=a.id+'>'+b.id;if(seen.has(key))return;seen.add(key);edges.push({a,b,kind,day,curve:curve(a,b)});}
 if(!d)filteredRegions().forEach(r=>add(E.ORIGIN,{id:r.id,coord:r.center},'national'));
 else{result.edges.forEach(e=>add(point(e.from),point(e.to),'selected',e.day));if(!recommendationCache.has(d.id))recommendationCache.set(d.id,d.courses.map((c,i)=>E.schedule(d,E.createPlan(d,i))));recommendationCache.get(d.id).forEach(r=>r.edges.forEach(e=>add(point(e.from),point(e.to),'alternate',e.day)));}
 edges.sort((a,b)=>(a.kind==='selected'?1:0)-(b.kind==='selected'?1:0));
 $('routeLayer').innerHTML=edges.map((e,i)=>{const selected=e.kind==='selected',national=e.kind==='national',color=selected?'#ead39b':national?'#b0c5d5':'#93a8b8';return `<path d="${curvePath(e.curve)}" fill="none" stroke="${color}" stroke-opacity="${selected?.62:national?.46:.28}" stroke-width="${selected?1.9:national?1.6:1.2}" ${!selected?'stroke-dasharray="5 7"':''} vector-effect="non-scaling-stroke"/>`+Array.from({length:national?3:2},(_,j)=>`<g id="flow-${i}-${j}"><path d="M-5-4L0 0-5 4M0-4L5 0 0 4" fill="none" stroke="${color}" stroke-width="${national?1.7:1.5}" stroke-linecap="round" stroke-linejoin="round"/></g>`).join('');}).join('');state.flows=edges.map((e,i)=>({...e,arrows:Array.from({length:e.kind==='national'?3:2},(_,j)=>$('flow-'+i+'-'+j))}));if(!state.playback){$('activeTrail').setAttribute('d','');$('movingArrow').style.display='none';}}
function paintMap(){$('mapSvg').setAttribute('viewBox',`${state.camera.x} ${state.camera.y} ${state.camera.w} ${state.camera.h}`);updatePins();paintPlaybackMarker();}
function paintFlow(){const v=state.camera,scale=v.w/state.width;state.flows.forEach((e,i)=>e.arrows.forEach((el,j)=>{const t=motion.matches?(j+1)/(e.arrows.length+1):(state.flowClock/(e.kind==='selected'?7600:10000)+j/e.arrows.length+i*.071)%1,c=e.curve,p=curvePoint(c,t),dx=2*((1-t)*(c.c.x-c.p.x)+t*(c.q.x-c.c.x)),dy=2*((1-t)*(c.c.y-c.p.y)+t*(c.q.y-c.c.y));el.style.display=p.x<v.x||p.x>v.x+v.w||p.y<v.y||p.y>v.y+v.h?'none':'';el.style.opacity=String((e.kind==='selected'?.88:e.kind==='national'?.72:.48)*Math.min(1,t*12,(1-t)*12));el.setAttribute('transform',`translate(${p.x} ${p.y}) scale(${scale}) rotate(${Math.atan2(dy,dx)*180/Math.PI})`);}));}
function playEdges(){let edges=result?.edges.filter(e=>e.day===state.day)||[];if(state.fromPoint){const p=point(state.fromPoint);if(!p)return[];const i=edges.findIndex(e=>e.from===p.id);if(i>=0)edges=edges.slice(i);else if(edges.length){const next=point(edges[0].to),v=E.travel(region(),p,next,plan().mode);edges=[{from:p.id,to:next.id,day:state.day,mode:v.mode,minutes:v.minutes},...edges.slice(1)];}}return edges.filter(e=>e.from!==e.to&&point(e.from)&&point(e.to));}
function playbackPoint(id){return id==='busan'?E.origin(region(),state.playback?.edges[state.playIndex]?.to==='busan'):point(id);}
function updatePlaybackControls(){const playback=state.playback,arrival=playback?.kind==='arrival',label=state.playing?(arrival?'Ⅱ 이동 멈춤':'Ⅱ 일시정지'):playback?'▶ 이어 재생':'▶ 일정 시작';for(const id of ['playRoute','mapPlay']){const b=$(id);if(b){b.textContent=label;b.setAttribute('aria-label',label.replace(/[▶Ⅱ]/g,'').trim());b.setAttribute('aria-pressed',String(state.playing));}}if($('mapPlayback'))$('mapPlayback').hidden=!region();if($('skipArrival'))$('skipArrival').hidden=!arrival;if($('arrivalReplay'))$('arrivalReplay').hidden=arrival;}
function stopPlayback(){state.playing=false;state.playback=null;state.fromPoint=null;state.playIndex=0;state.elapsed=0;state.tween=null;if($('playCaption'))$('playCaption').hidden=true;if($('activeTrail'))$('activeTrail').setAttribute('d','');if($('movingArrow'))$('movingArrow').style.display='none';updatePlaybackControls();}
function startPlayback(kind,edges){setPane('map');if(state.plannerExpanded){state.plannerExpanded=false;renderPlanner();}stopPlayback();if(!edges.length){toast('재생할 이동 경로가 없습니다. 장소를 추가해 주세요.');return;}state.playback={kind,edges:edges.map(e=>({...e})),leg:null};state.playIndex=0;state.elapsed=0;state.playing=true;setPlayCamera();updatePlaybackControls();$('viewport').closest('.map-frame')?.scrollIntoView({behavior:motion.matches?'auto':'smooth',block:'nearest'});}
function startArrival(){if(!region())return;const edge=result?.edges.find(e=>e.from==='busan');if(edge)startPlayback('arrival',[edge]);else fitSelected();}
function togglePlay(from=null){if(!region())return;if(state.playing&&!from){pauseMap();return;}if(!from&&state.playback){setPane('map');if(state.plannerExpanded){state.plannerExpanded=false;renderPlanner();}state.playing=true;state.tween=null;state.playback.resume={from:{...state.camera},elapsed:0};showPlayCaption();updatePlaybackControls();$('viewport').closest('.map-frame')?.scrollIntoView({behavior:motion.matches?'auto':'smooth',block:'nearest'});return;}state.fromPoint=from;const edges=playEdges();startPlayback('day',edges);}
function showPlayCaption(){const e=state.playback?.edges[state.playIndex];if(!e)return;const a=playbackPoint(e.from),target=playbackPoint(e.to);$('playCaption').hidden=false;$('playCaption').innerHTML=`<small>${state.playback.kind==='arrival'?'부산에서 '+esc(region().name)+'으로':E.date(e.day)} · ${MODES[e.mode]||'경로 미리보기'}${e.minutes?' '+e.minutes+'분':''}</small><b>${esc(a.name)} → ${esc(target.name)}</b><p>${esc(target.desc||'도착 후 후보 장소를 살펴보세요.')}</p>`;}
const smoothStep=t=>t*t*(3-2*t);
function setPlayCamera(){const e=state.playback?.edges[state.playIndex];if(!e){finishPlayback();return;}const a=playbackPoint(e.from),b=playbackPoint(e.to),c=curve(a,b),distance=Math.hypot(c.q.x-c.p.x,c.q.y-c.p.y),intercity=e.from==='busan'||e.to==='busan';state.playback.leg={curve:c,startCamera:{...state.camera},duration:intercity?4200:2600,startSpan:intercity?E.clamp(distance*.5,24,145):E.clamp(distance*.8,4,32),endSpan:intercity?12:E.clamp(distance*.55,4,22),progress:0};state.elapsed=0;state.tween=null;showPlayCaption();updatePlaybackControls();}
function followView(p,span){const ratio=state.width/state.height,w=span*Math.max(1,ratio),h=w/ratio;return{x:p.x-w/2,y:p.y-h*.46,w,h};}
function blendView(a,b,t){return{x:lerp(a.x,b.x,t),y:lerp(a.y,b.y,t),w:lerp(a.w,b.w,t),h:lerp(a.h,b.h,t)};}
function paintPlaybackMarker(){const leg=state.playback?.leg;if(!leg)return;const c=leg.curve,t=leg.progress,p=curvePoint(c,t),dx=2*((1-t)*(c.c.x-c.p.x)+t*(c.q.x-c.c.x)),dy=2*((1-t)*(c.c.y-c.p.y)+t*(c.q.y-c.c.y));$('activeTrail').setAttribute('d',curvePath({p:c.p,c:{x:lerp(c.p.x,c.c.x,t),y:lerp(c.p.y,c.c.y,t)},q:p}));$('movingArrow').style.display='';$('movingArrow').setAttribute('transform',`translate(${p.x} ${p.y}) scale(${state.camera.w/state.width}) rotate(${Math.atan2(dy,dx)*180/Math.PI})`);}
function finishPlayback(){const kind=state.playback?.kind;stopPlayback();if(kind==='arrival')fitSelected();}
function pauseMap(){state.playing=false;state.tween=null;if($('playCaption'))$('playCaption').hidden=true;updatePlaybackControls();}
function tick(now){const dt=lastFrame?Math.min(now-lastFrame,50):0;lastFrame=now;state.flowClock+=dt;if(state.tween){const tw=state.tween,t=tw.duration?E.clamp((now-tw.start)/tw.duration,0,1):1;state.camera=blendView(tw.from,tw.to,smoothStep(t));if(t>=1)state.tween=null;paintMap();}
 if(state.playing&&state.playback?.leg){const playback=state.playback,leg=playback.leg,resuming=Boolean(playback.resume);if(!resuming)state.elapsed+=dt;const t=E.clamp((state.elapsed-500)/leg.duration,0,1);leg.progress=smoothStep(t);const p=curvePoint(leg.curve,leg.progress),view=followView(p,lerp(leg.startSpan,leg.endSpan,leg.progress));if(resuming){playback.resume.elapsed+=dt;const f=smoothStep(E.clamp(playback.resume.elapsed/400,0,1));state.camera=motion.matches?view:blendView(playback.resume.from,view,f);if(f>=1)delete playback.resume;}else if(motion.matches){if(state.elapsed>=500+leg.duration)state.camera=view;}else state.camera=blendView(leg.startCamera,view,smoothStep(E.clamp(state.elapsed/500,0,1)));paintMap();if(!resuming&&state.elapsed>=500+leg.duration+550){state.playIndex++;setPlayCamera();}}
 if(now-paintTime>40){paintFlow();paintTime=now;}requestAnimationFrame(tick);}

function position(e){const v=$('viewport'),r=v.getBoundingClientRect();return{x:(e.clientX-r.left)*v.offsetWidth/r.width-v.clientLeft,y:(e.clientY-r.top)*v.offsetHeight/r.height-v.clientTop};}
function zoom(factor,at={x:state.width/2,y:state.height/2},duration=150){const v={...(state.tween?.to||state.camera)},w=E.clamp(v.w*factor,.6,1500),h=w*state.height/state.width,ax=at.x/state.width,ay=at.y/state.height;pauseMap();animateView({x:v.x+v.w*ax-w*ax,y:v.y+v.h*ay-h*ay,w,h},duration);}
function beginGesture(moved=false){const pts=[...pointers.values()];if(!pts.length){gesture=null;return;}const center=pts.length>1?{x:(pts[0].x+pts[1].x)/2,y:(pts[0].y+pts[1].y)/2}:pts[0],v={...state.camera};gesture={camera:v,center,moved:pts.length>1||moved,distance:pts.length>1?Math.max(1,Math.hypot(pts[1].x-pts[0].x,pts[1].y-pts[0].y)):0,anchor:{x:v.x+center.x/state.width*v.w,y:v.y+center.y/state.height*v.h}};}
function clearGesture(){pendingTap=null;const ids=[...pointers.keys()];pointers.clear();gesture=null;ids.forEach(id=>{if($('viewport').hasPointerCapture?.(id))$('viewport').releasePointerCapture(id);});$('viewport').classList.remove('dragging');}
function onPointerDown(e){if(e.button!==0||e.target.closest('.map-buttons,a')||pointers.size>=2)return;if(!pointers.size){ignoreClickUntil=0;pendingTap=null;}pauseMap();pointers.set(e.pointerId,position(e));beginGesture(gesture?.moved||false);}
