const minutes=v=>{if(!/^\d{2}:\d{2}$/.test(v))return null;const[h,m]=v.split(':').map(Number);return E.clamp(h*60+m,0,1439);};
function handleAction(action){
 if(action==='info'){info();return;}if(action==='choose-region'){chooseRegion();return;}if(!plan())return;
 if(action==='planner-menu'){modal('일정 관리',`<div class="planner-menu"><button data-action="undo" ${undo.length?'':'disabled'}>${icon('undo')} 되돌리기</button><button data-action="redo" ${redo.length?'':'disabled'}>${icon('redo')} 다시 실행</button><button data-action="settings">${icon('settings')} 출발·이동·숙소</button><button data-action="save">${icon('save')} 저장·가져오기</button></div>`);$('dialog').dataset.kind='planner-menu';}else if(action==='add-place')openPlacePicker();else if(action==='time-in')changeTimeZoom(.5);else if(action==='time-out')changeTimeZoom(-.5);else if(action==='apply-move'){const uid=state.editUid,day=Number($('moveDay').value),index=Number($('movePosition').value);if(moveStop(uid,day,index)){ $('dialog').close();toast('방문 순서를 변경했습니다.',true);}}else if(action==='course-info')courseInfo();else if(action==='day-list')dayList();else if(action==='schedule-info')scheduleInfo();else if(action==='expand-planner'){state.plannerExpanded=!state.plannerExpanded;renderPlanner();}else if(action==='settings')settings();else if(action==='save')saveDialog();else if(action==='play')togglePlay();
 else if(action==='blank'||action==='reset'){$('dialog').close();resetPlan(action==='blank');}
 else if(action==='undo'||action==='redo')historyStep(action==='undo');
 else if(action==='all-places'){setPane('places');state.type='all';state.query='';renderCandidatePanel();$('candidatePanel').scrollIntoView({behavior:motion.matches?'auto':'smooth',block:'nearest'});}
 else if(action==='arrival')startArrival();
 else if(action==='skip-arrival'){stopPlayback();fitSelected();}
 else if(action==='fit-day')focusTimeline();
 else if(action==='detail-selected'){const v=selectedItem();if(v){closeStopEditor();openDetail(v.item.poi);}}
 else if(action==='remove')removeStop(state.editUid);
 else if(action==='clear-start'){const v=selectedItem();if(v)mutate(()=>{v.item.start=null;v.item.travel=null;});}
 else if(action==='apply-settings'){const values={mode:$('defaultMode').value,hotel:$('hotelSelect').value,friday:$('friday').checked,departFriday:minutes($('departFriday').value)??1140,departSaturday:minutes($('departSaturday').value)??360,busanAccess:E.clamp(Number($('busanAccess')?.value??30),0,180),starts:[...$('dialogBody').querySelectorAll('[data-day-start]')].map(e=>minutes(e.value)??540)};$('dialog').close();if(!values.friday&&state.day===-1)state.day=0;mutate(p=>Object.assign(p,values));}
 else if(action==='download-json')download('NovemberTrip-plans.json',JSON.stringify({kind:'NovemberTrip',version:1,exported:new Date().toISOString(),plans:saved},null,2),'application/json');
 else if(action==='download-html'){const clone=document.documentElement.cloneNode(true);clone.querySelectorAll('dialog').forEach(e=>e.removeAttribute('open'));clone.dataset.startRegion=state.region||'';clone.dataset.startCourse=String(state.course);clone.querySelector('#embeddedPlans').textContent=JSON.stringify(saved).replace(/</g,'\\u003c');clone.querySelector('#toast').setAttribute('hidden','');download('travel.html','<!doctype html>\n'+clone.outerHTML,'text/html;charset=utf-8');}
}
